import{_ as s,l as n,o as e,c as l,v as t,p as o,x as r,d as p,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"步进器与扫描投影","description":"","frontmatter":{"title":"步进器与扫描投影","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/stepper-vs-scanner.md","filePath":"litho/stepper-vs-scanner.md","lastUpdated":1789023840000}'),E={name:"litho/stepper-vs-scanner.md"};function d(A,a,c,B,C,_){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="步进器与扫描投影" tabindex="-1">步进器与扫描投影 <a class="header-anchor" href="#步进器与扫描投影" aria-label="Permalink to &quot;步进器与扫描投影&quot;">​</a></h1><div class="epigraph"><p>步进器一次把整个场印在晶圆上再挪步；扫描投影只照亮一条狭缝，掩模与晶圆同步扫过，镜头只需在狭缝里做到均匀。</p><footer>—— 据 Levinson 对 step-and-repeat 与 step-and-scan 的区分，以及 ASML 对扫描机架构的公开说明整理</footer></div><p><a href="/litho/twinscan-dual-stage">上一课</a>（双工件台 Twinscan 提高产能）。在此之上，测量与曝光拆到两张晶圆台上并行，默认光学已经是扫描投影。缺口是：还没有把「为什么是扫、而不是整场一次闪」写成合同。本课钉步进器（step-and-repeat）与扫描机（step-and-scan）的差别。成像栏到此结束；记录介质从<a href="/litho/car-resist">下一课</a>的化学放大胶开始，不再回头解释工件台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双台解决的是片周期里测量与曝光谁先谁后。它不回答：一场 \\(26\\,\\mathrm{mm}\\times 33\\,\\mathrm{mm}\\) 量级的像，究竟是镜头瞬时满视场投影，还是一条狭缝扫出来的。早期步进器走前一条：掩模（reticle）静止，快门开一次，整场落在晶圆上，然后工件台步进到下一场。场一大，镜头必须在全场同时消像差、同时均匀照明，玻璃口径与均匀性一起爆炸。</p><p>扫描投影把照明收成与扫描方向垂直的狭缝，掩模台与晶圆台按缩比同步运动，狭缝扫过整场。瞬时视场只是狭缝宽度，镜头规格按「一条缝」写，有效曝光场可以更大、场内 CD 更匀。缺口因此是这场运动学，不是再讲一遍双台交换。</p><h3 id="扫描不是为了「更快闪灯」" tabindex="-1">扫描不是为了「更快闪灯」 <a class="header-anchor" href="#扫描不是为了「更快闪灯」" aria-label="Permalink to &quot;扫描不是为了「更快闪灯」&quot;">​</a></h3><p>准分子脉冲在扫描方向上被积分成一条连续剂量。速度由脉冲能量、重复频率和目标剂量决定，不是步进器快门时间的线性升级。扫描同步误差（掩模与晶圆相对位置）会直接变成场内套刻与有效离焦——上一课的双台密网格，正是为这条同步服务的。把扫描理解成「步进器加一条传送带」，会漏掉同步就是光学的一部分。</p><p><span class="marginnote">缩比仍是典型的 \\(4\\times\\)：掩模线性尺寸是晶圆的四倍。步进器和扫描机都可以是缩小投影；差别在场如何被填满，不在缩比本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步进器：对准 → 整场曝光 → 步进。照明要铺满矩形场，光瞳在曝光瞬间对全场同一套。适合场不大、\\(\\mathrm{NA}\\) 不太高、套刻与 CD 均匀性要求较松的层。</p><p>扫描机：对准与调平之后，按场做步进–扫描。照明光瞳仍由 <a href="/litho/partial-coherence">\\(\\sigma\\)</a> 描述，但瞬时物面只是狭缝下的那一条。场内均匀性靠扫描积分，而不是靠把照明做成完美的大矩形。ASML 量产 DUV / EUV 平台都走这条，TWINSCAN 是它的双台版本。</p><h3 id="何时步进器仍在" tabindex="-1">何时步进器仍在 <a class="header-anchor" href="#何时步进器仍在" aria-label="Permalink to &quot;何时步进器仍在&quot;">​</a></h3><p>成熟节点、后段松层、某些封装与化合物产线，步进器或接近整场曝光的机型仍在用：光学简单、同步误差这项不存在。临界层在大场、高 \\(\\mathrm{NA}\\)、浅焦深下，扫描是默认。本课不把「扫描=先进、步进=落后」写成道德；写成场尺寸与镜头均匀性的几何约束。</p>',14)),(e(),o(h,null,{default:r(()=>[m(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20STP%5B%22%E6%AD%A5%E8%BF%9B%E5%99%A8%3A%20%E6%95%B4%E5%9C%BA%E4%B8%80%E6%AC%A1%E6%88%90%E5%83%8F%22%5D%20--%3E%20LENS%5B%22%E9%95%9C%E5%A4%B4%E9%A1%BB%E5%85%A8%E5%9C%BA%E5%90%8C%E6%97%B6%E5%A5%BD%22%5D%0A%20%20SCN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%3A%20%E7%8B%AD%E7%BC%9D%E5%90%8C%E6%AD%A5%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20SLIT%5B%22%E7%9E%AC%E6%97%B6%E8%A7%86%E5%9C%BA%20%3D%20%E7%8B%AD%E7%BC%9D%22%5D%0A%20%20SLIT%20--%3E%20FIELD%5B%22%E6%9C%89%E6%95%88%E5%9C%BA%E6%9B%B4%E5%A4%A7%20%2F%20CD%20%E6%9B%B4%E5%8C%80%22%5D%0A%20%20SCN%20--%3E%20SYNC%5B%22%E6%8E%A9%E6%A8%A1-%E6%99%B6%E5%9C%86%E5%90%8C%E6%AD%A5%22%5D%0A%20%20SYNC%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%E4%B8%8E%E6%9C%89%E6%95%88%E7%84%A6%E6%B7%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>整场成像时，视场边缘的主光线角、畸变、彗差必须与中心同时合格。狭缝扫描把「同时」改成「沿扫描方向积分」：每一点看到的是狭缝里那一小段镜头指纹的时间平均。这降低了对全场静态均匀性的要求，但加上运动轴：扫描方向的速度比必须锁在缩比上，垂直方向的狭缝必须与镜头像场匹配。</p><p>产能叙事与上一课衔接：扫描机的曝光时间是狭缝扫过场长的时间；双台把测量藏进这段时间。步进器没有「扫场」这笔，片周期结构不同，双台的收益账也不同。不要用 NXT 的 wph 去外推一台 i 线步进器。</p><p>照度均匀性在步进器里是二维场图；在扫描器里首先是狭缝积分均匀，再叠加扫描速度抖动。剂量控制从「快门时间」变成「速度 × 狭缝强度」。同步误差会变成场内畸变与 CD 指纹，这是步进器没有的误差通道。</p><p><span class="marginnote">ASML 浸没机公开场尺寸常见 \\(26\\,\\mathrm{mm}\\times 33\\,\\mathrm{mm}\\)（晶圆侧）。\\(33\\,\\mathrm{mm}\\) 是扫描方向拼出的场高，\\(26\\,\\mathrm{mm}\\) 受镜头瞬时场宽限制。不要把两个数字都当成「镜头一次成像的圆直径」。</span></p><h3 id="本课钉死的词" tabindex="-1">本课钉死的词 <a class="header-anchor" href="#本课钉死的词" aria-label="Permalink to &quot;本课钉死的词&quot;">​</a></h3><p>后课说「扫描机」就是 step-and-scan；说「步进器」就是 step-and-repeat。Twinscan 是扫描机上的双工件台，不是第三种成像几何。狭缝、同步、场尺寸，本课以后不再重讲。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论浸没喷淋头如何跟着狭缝走，那是<a href="/litho/arf-immersion">浸没</a>的流体缺口。也不把 EUV 真空磁浮台的细节搬进来。扫描同步规格属于套刻预算，具体标记结构在计量课。胶的灵敏度会改扫描速度（剂量不够就扫慢），但那是下一课程的化学，不在运动学里展开。</p><p>场尺寸数字随机型变：ASML 浸没公开规格常用约 \\(26\\,\\mathrm{mm}\\times 33\\,\\mathrm{mm}\\) 的扫描场，不要把它写进所有历史步进器。步进器的场受镜头直径限制，往往更小，这正是当年改扫描的动机之一。</p><p><span class="marginnote">「Stepper」在口语里有时被用来统称所有光刻机。本课以后禁止这种混名：步进器是整场闪，扫描机是狭缝扫。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>步进器整场一次投影；扫描机用狭缝同步扫出有效场。</li><li>扫描降低对全场静态镜头均匀性的要求，把同步误差写进光学。</li><li>缩比与双台是正交的：TWINSCAN 是扫描机的产能架构。</li><li>成熟松层仍可用步进器；临界大场默认扫描。</li><li>成像课程到此结束，下一课进入抗蚀剂。</li><li>出处：Levinson, <em>Principles of Lithography</em>；ASML 对扫描投影与 TWINSCAN 的公开说明。</li></ul>',13))])}const S=s(E,[["render",d]]);export{f as __pageData,S as default};
